+    CHECK_THAT(*reason, Contains(std::to_string(kGranted)));
+    CHECK_THAT(*reason, Contains(std::to_string(kRequested)));
+    CHECK_THAT(*reason, Contains("freed 0 bytes"));
+    CHECK_THAT(*reason, Contains("disk tier not configured"));
